import { test, expect } from '@playwright/test';

test.describe('Notification Dismissal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display notification', async ({ page }) => {
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();
  });

  test('should dismiss notification when close button is clicked', async ({ page }) => {
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();
    const notification = page.getByRole('alert');
    await expect(notification).not.toBeVisible();
  });
});
